ALTER TYPE "OrderStatus" ADD VALUE IF NOT EXISTS 'CANCELLED_BY_CUSTOMER';
ALTER TABLE "Order" ADD COLUMN "expiresAt" TIMESTAMP(3), ADD COLUMN "activePickupCodeHash" TEXT, ADD COLUMN "cancelledToBalanceAt" TIMESTAMP(3);
CREATE TABLE "GiftTransfer" ("id" TEXT PRIMARY KEY, "originalOrderId" TEXT NOT NULL, "senderCustomerId" TEXT NOT NULL, "recipientCustomerId" TEXT, "recipientPhoneNormalized" TEXT NOT NULL, "status" TEXT NOT NULL, "referralId" TEXT, "invitationTokenHash" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "acceptedAt" TIMESTAMP(3), "redeemedAt" TIMESTAMP(3), "expiredAt" TIMESTAMP(3), "cancelledAt" TIMESTAMP(3), "transferredBy" TEXT NOT NULL, "correlationId" TEXT NOT NULL, "metadata" JSONB);
CREATE UNIQUE INDEX "GiftTransfer_originalOrderId_key" ON "GiftTransfer"("originalOrderId");
CREATE INDEX "GiftTransfer_senderCustomerId_idx" ON "GiftTransfer"("senderCustomerId"); CREATE INDEX "GiftTransfer_recipientCustomerId_idx" ON "GiftTransfer"("recipientCustomerId"); CREATE INDEX "GiftTransfer_recipientPhoneNormalized_idx" ON "GiftTransfer"("recipientPhoneNormalized"); CREATE INDEX "GiftTransfer_status_expiresAt_idx" ON "GiftTransfer"("status","expiresAt"); CREATE INDEX "GiftTransfer_correlationId_idx" ON "GiftTransfer"("correlationId"); CREATE INDEX "GiftTransfer_referralId_idx" ON "GiftTransfer"("referralId");
CREATE TABLE "GiftInvitation" ("id" TEXT PRIMARY KEY, "giftTransferId" TEXT NOT NULL REFERENCES "GiftTransfer"("id"), "recipientPhoneNormalized" TEXT NOT NULL, "tokenHash" TEXT NOT NULL UNIQUE, "expiresAt" TIMESTAMP(3) NOT NULL, "status" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "acceptedAt" TIMESTAMP(3), "metadata" JSONB);
CREATE INDEX "GiftInvitation_recipientPhoneNormalized_status_idx" ON "GiftInvitation"("recipientPhoneNormalized","status"); CREATE INDEX "GiftInvitation_expiresAt_idx" ON "GiftInvitation"("expiresAt");
CREATE TABLE "GiftRecipientClaim" ("id" TEXT PRIMARY KEY, "giftTransferId" TEXT NOT NULL UNIQUE REFERENCES "GiftTransfer"("id"), "recipientCustomerId" TEXT NOT NULL, "verifiedPhoneNormalized" TEXT NOT NULL, "claimedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "correlationId" TEXT NOT NULL, "metadata" JSONB);
CREATE INDEX "GiftRecipientClaim_recipientCustomerId_idx" ON "GiftRecipientClaim"("recipientCustomerId"); CREATE INDEX "GiftRecipientClaim_correlationId_idx" ON "GiftRecipientClaim"("correlationId");
CREATE TABLE "GiftRedemption" ("id" TEXT PRIMARY KEY, "giftTransferId" TEXT NOT NULL REFERENCES "GiftTransfer"("id"), "recipientCustomerId" TEXT NOT NULL, "authorizationHash" TEXT NOT NULL UNIQUE, "status" TEXT NOT NULL, "issuedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "expiresAt" TIMESTAMP(3) NOT NULL, "usedAt" TIMESTAMP(3), "correlationId" TEXT NOT NULL, "metadata" JSONB);
CREATE INDEX "GiftRedemption_giftTransferId_status_idx" ON "GiftRedemption"("giftTransferId","status"); CREATE INDEX "GiftRedemption_recipientCustomerId_idx" ON "GiftRedemption"("recipientCustomerId"); CREATE INDEX "GiftRedemption_expiresAt_idx" ON "GiftRedemption"("expiresAt"); CREATE INDEX "GiftRedemption_correlationId_idx" ON "GiftRedemption"("correlationId");
CREATE TABLE "GiftReferralLink" ("id" TEXT PRIMARY KEY, "giftTransferId" TEXT NOT NULL UNIQUE REFERENCES "GiftTransfer"("id"), "referralId" TEXT, "referralSource" TEXT NOT NULL DEFAULT 'GIFT_TRANSFER', "stage" TEXT NOT NULL, "referrerCustomerId" TEXT NOT NULL, "referredCustomerId" TEXT, "firstOwnPurchaseAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "metadata" JSONB);
CREATE INDEX "GiftReferralLink_referralId_idx" ON "GiftReferralLink"("referralId"); CREATE INDEX "GiftReferralLink_referrerCustomerId_idx" ON "GiftReferralLink"("referrerCustomerId"); CREATE INDEX "GiftReferralLink_referredCustomerId_idx" ON "GiftReferralLink"("referredCustomerId");
CREATE TABLE "NotificationDeliveryAttempt" ("id" TEXT PRIMARY KEY, "notificationId" TEXT NOT NULL, "recipientCustomerId" TEXT, "channel" TEXT NOT NULL, "providerMessageId" TEXT, "status" TEXT NOT NULL, "attemptedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "deliveredAt" TIMESTAMP(3), "openedAt" TIMESTAMP(3), "failedAt" TIMESTAMP(3), "failureCode" TEXT, "correlationId" TEXT NOT NULL, "metadata" JSONB);
CREATE UNIQUE INDEX "NotificationDeliveryAttempt_notificationId_channel_key" ON "NotificationDeliveryAttempt"("notificationId","channel"); CREATE INDEX "NotificationDeliveryAttempt_recipientCustomerId_idx" ON "NotificationDeliveryAttempt"("recipientCustomerId"); CREATE INDEX "NotificationDeliveryAttempt_status_attemptedAt_idx" ON "NotificationDeliveryAttempt"("status","attemptedAt"); CREATE INDEX "NotificationDeliveryAttempt_correlationId_idx" ON "NotificationDeliveryAttempt"("correlationId");
